package com.autojobapply.resume;
import com.autojobapply.model.Resume; import org.apache.pdfbox.Loader; import org.apache.pdfbox.text.PDFTextStripper; import org.apache.poi.hwpf.HWPFDocument; import org.apache.poi.hwpf.extractor.WordExtractor; import org.apache.poi.xwpf.extractor.XWPFWordExtractor; import org.apache.poi.xwpf.usermodel.XWPFDocument;
import java.io.*; import java.nio.file.*; import java.util.*; import java.util.regex.*;
public final class ResumeParser {
 public Resume parse(Path file) throws IOException { if(!Files.isRegularFile(file)) throw new FileNotFoundException("Resume not found: "+file+". Put your .docx, .doc, or .pdf resume there."); String text=read(file); if(text.isBlank()) throw new IOException("No readable text in resume: "+file); String email=find(text,"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}"); String phone=find(text,"(?:\\+?1[ .-]?)?(?:\\(?\\d{3}\\)?[ .-]?)\\d{3}[ .-]\\d{4}"); String name=text.lines().filter(s->s.trim().matches("[A-Za-z .'-]{3,60}")).findFirst().orElse("").trim(); return new Resume(text,name,email,phone,terms(text)); }
 private String read(Path p) throws IOException { String n=p.getFileName().toString().toLowerCase(Locale.ROOT); if(n.endsWith(".pdf")){try(var d=Loader.loadPDF(p.toFile())){return new PDFTextStripper().getText(d);}} if(n.endsWith(".docx")){try(var d=new XWPFDocument(Files.newInputStream(p));var x=new XWPFWordExtractor(d)){return x.getText();}} if(n.endsWith(".doc")){try(var d=new HWPFDocument(Files.newInputStream(p));var x=new WordExtractor(d)){return x.getText();}} throw new IOException("Unsupported resume format: "+p); }
 private String find(String s,String regex){Matcher m=Pattern.compile(regex).matcher(s);return m.find()?m.group():"";} private Set<String> terms(String s){return Arrays.stream(s.toLowerCase().split("[^a-z0-9+#.]+" )).filter(x->x.length()>1).collect(java.util.stream.Collectors.toSet());}
}
